const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Process return for the Northline Wool Blend Throw Blanket
db.prepare(\"UPDATE orders SET status = 'return requested', return_items = ?, return_payment_method_id = ? WHERE order_id = 'ORD-AC715B'\").run(
  JSON.stringify(['ITEM-EEA343']),
  'cc_ab64993a'
);

// Update the item status
db.prepare(\"UPDATE order_items SET item_status = 'return requested', refund_method = 'cc_ab64993a', refund_amount = 34 WHERE oi_id = 'ITEM-EEA343'\").run();

// Verify
const order = db.prepare(\"SELECT order_id, status, return_items, return_payment_method_id FROM orders WHERE order_id = 'ORD-AC715B'\").get();
console.log('Order updated:', JSON.stringify(order, null, 2));
const item = db.prepare(\"SELECT oi_id, name, item_status, refund_amount, refund_method FROM order_items WHERE oi_id = 'ITEM-EEA343'\").get();
console.log('Item updated:', JSON.stringify(item, null, 2));
"

